/* Admin visual refresh 2026 */
:root{--navy:#10251f;--muted:#718079;--green:#00704a;--line:#e4eae5;--bg:#f2f6f3;--white:#fff;--red:#b42318;--amber:#a66a13;--purple:#6553a6;--cyan:#17858a}
body{background:radial-gradient(ellipse at 83% 0,#e4f1e9 0,transparent 30%),linear-gradient(135deg,#f3f6f4,#f5f5f8 55%,#f8f5ee);color:#1d2d27}
.shell{grid-template-columns:264px minmax(0,1fr)}
.side{z-index:5;background:linear-gradient(180deg,#0d3a2b 0%,#082e23 55%,#08291f 100%);border:0;color:#f3fff7;box-shadow:10px 0 35px #0d392b12}
.side:before{content:"";position:absolute;inset:0 0 auto;height:220px;background:radial-gradient(ellipse at 16% 0,#2ba87735,transparent 68%);pointer-events:none}
.brand{position:relative;color:#fff;padding:4px 11px 27px;letter-spacing:.03em}
.mark{background:linear-gradient(145deg,#d8b46b,#f0d99e);color:#12392b;box-shadow:0 6px 18px #0002;border-radius:13px}
.brand small{color:#9bc3ae}
.nav-label{color:#8fb7a1}
.nav a,.side-bottom a{position:relative;color:#c5d8cd;border:1px solid transparent;transition:transform .2s,background .2s,color .2s,border-color .2s}
.nav a:hover{transform:translateX(3px);background:#ffffff0d;color:white;border-color:#ffffff12}
.nav a.active{background:linear-gradient(100deg,#d8b46b,#f0d99e);color:#17382c;border-color:#f8e6b8;box-shadow:0 8px 20px #0002}
.nav a.active .ico{color:#174b37}
.side-bottom{border-color:#ffffff20}
.side-bottom a:hover{background:#ffffff0d;color:#fff}
.admin-person{position:relative;margin-top:8px;border-radius:14px;background:#ffffff0b;border:1px solid #ffffff13}
.avatar{background:#d7efe1;color:#006747;box-shadow:0 4px 12px #0002}
.admin-person b{color:#fff}.admin-person small{color:#9bc3ae}
.content{min-width:0}
.topbar{position:sticky;top:0;z-index:4;background:#ffffffd9;border-color:#e0e9e2;box-shadow:0 4px 20px #143c2908;backdrop-filter:blur(16px)}
.crumb{color:#718079}.crumb b{color:#174c38}
.toplinks a{padding:8px 12px;border:1px solid #e4eae5;border-radius:999px;background:#fff;color:#315947;transition:transform .2s,box-shadow .2s}
.toplinks a:hover{transform:translateY(-2px);box-shadow:0 7px 17px #174c3815}
.main{max-width:1600px;padding-top:34px}
.pagehead h1{color:#132b21;font-size:29px;letter-spacing:-.045em}
.pagehead h1:after{content:"";display:block;width:48px;height:3px;margin-top:11px;border-radius:8px;background:linear-gradient(90deg,#00704a,#d3ab58)}
.pagehead p{color:#738078}
.filters,.card{border-color:#e4eae5;border-radius:15px;box-shadow:0 8px 28px #173c2b08}
.filters{background:#ffffffd9;backdrop-filter:blur(10px)}
.filters input:focus,.filters select:focus,.field input:focus,.field select:focus,.field textarea:focus{outline:0;border-color:#68a78a;box-shadow:0 0 0 4px #00704a12}
.btn{border-radius:9px;transition:transform .2s,box-shadow .2s,background .2s,border-color .2s}
.btn:hover{transform:translateY(-1px);box-shadow:0 5px 14px #132f2215}
.btn.primary{background:linear-gradient(120deg,#00704a,#07845a);border-color:#00704a;box-shadow:0 5px 13px #00704a20}
.btn.primary:hover{background:linear-gradient(120deg,#07845a,#009468);box-shadow:0 8px 20px #00704a35}
.cards{gap:16px;margin:20px 0}
.metric{position:relative;isolation:isolate;overflow:hidden;min-height:148px;padding:19px 20px;border:1px solid #e5ebe6;border-radius:16px;background:linear-gradient(145deg,#fff 0%,#fbfdfb 100%);box-shadow:0 9px 25px #163b2909;transition:transform .28s,box-shadow .28s,border-color .28s;animation:adminFloatIn .5s both}
.metric:nth-child(2){animation-delay:.06s}.metric:nth-child(3){animation-delay:.12s}.metric:nth-child(4){animation-delay:.18s}
.metric:after{content:"";position:absolute;z-index:-1;right:-30px;bottom:-65px;width:160px;height:160px;border:1px solid #00704a12;border-radius:50%;box-shadow:0 0 0 18px #00704a05,0 0 0 36px #00704a03;transition:transform .5s}
.metric:hover{transform:translateY(-5px);border-color:#c9ded1;box-shadow:0 18px 38px #163b2916}
.metric:hover:after{transform:scale(1.13)}
.metric-head{color:#697970;font-weight:600}
.metric-icon{width:38px;height:38px;border-radius:12px;background:linear-gradient(145deg,#e5f4eb,#ccebd8);color:#00704a;font-size:17px;box-shadow:inset 0 0 0 1px #00704a0c}
.metric:nth-child(2) .metric-icon{background:linear-gradient(145deg,#fff1d6,#f7dfaa);color:#aa7419}
.metric:nth-child(3) .metric-icon{background:linear-gradient(145deg,#e6e2ff,#d4cff9);color:#6553a6}
.metric:nth-child(4) .metric-icon{background:linear-gradient(145deg,#dff5f4,#c5e9e7);color:#17858a}
.metric strong{margin:17px 0 6px;color:#152d23;font-size:29px;letter-spacing:-.045em}
.metric small{color:#8b9991}
.dashboard-grid{gap:17px}
.card{padding:21px;transition:box-shadow .25s,border-color .25s,transform .25s}
.dashboard-grid .card:hover{border-color:#d5e3d9;box-shadow:0 14px 34px #163b2910}
.card-title h2,.table-head h2{color:#183529}
.card-title p{color:#849188}
.chart{height:250px}
.chart-grid{stroke:#e9efea}
.legend{color:#718079}
.mini-row{color:#284536}
.bar{height:7px;background:#edf2ee;border-radius:99px}.bar i{background:linear-gradient(90deg,#00704a,#32a977);box-shadow:0 0 8px #00704a30}
.table-card{overflow:hidden}
.table-head{background:linear-gradient(110deg,#fff,#f8fbf8);border-color:#e8eee9}
.scroll{scrollbar-color:#b7cbbd #f3f6f3;scrollbar-width:thin}
th{background:#f7faf7;color:#728078}
th,td{border-color:#edf1ed}
tbody tr{transition:background .18s}
tbody tr:hover{background:#f6faf7}
td{color:#3d5146}
td b{color:#17372a}
.badge{background:#e7f5eb;color:#08784f;font-weight:700}
.badge.warn{background:#fff3dc;color:#9b6411}
.badge.off{background:#f0f2f1;color:#68736d}
.row-actions summary{border-color:#e2e9e3;border-radius:9px;transition:background .2s,color .2s,transform .2s}
.row-actions summary:hover{background:#eaf5ee;color:#00704a;transform:translateY(-1px)}
.menu{border-color:#dfe9e1;border-radius:12px;box-shadow:0 16px 35px #10251f24}
.table-note{background:#fbfdfb;color:#718079}
.staff-card{border-color:#e1e9e2;border-radius:14px;background:linear-gradient(145deg,#fff,#f9fcf9);box-shadow:0 7px 20px #163b2908;transition:transform .25s,box-shadow .25s}
.staff-card:hover{transform:translateY(-3px);box-shadow:0 14px 28px #163b2913}
.staff-meta span{color:#829188}.staff-meta b{color:#274739}
.notice{border:1px solid #cce9d5;border-radius:11px;box-shadow:0 6px 18px #00704a10}
.notice.err{border-color:#f3c7c2}
.period a{transition:all .2s}.period a:hover{transform:translateY(-1px);border-color:#9dc4aa}.period a.sel{background:linear-gradient(120deg,#00704a,#07845a);color:#fff;border-color:#00704a}
.admin-order-items,.account-order-items{box-shadow:0 3px 10px #10251f08}
@keyframes adminFloatIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:1050px){.shell{grid-template-columns:225px minmax(0,1fr)}}
@media(max-width:700px){.side{background:linear-gradient(100deg,#0d3a2b,#082e23);box-shadow:0 8px 24px #0d392b20}.nav a.active{box-shadow:none}.topbar{position:relative}.main{padding-top:20px}.metric{min-height:125px}.metric strong{font-size:23px}}
@media(prefers-reduced-motion:reduce){.metric,.staff-card,.btn,.nav a,.period a{animation:none!important;transition:none!important}}

/* Revenue chart interactive data points */
.chart-wrap{position:relative;width:100%;isolation:isolate}
.chart{overflow:visible;touch-action:pan-y}
.chart-hit{fill:transparent;stroke:transparent;cursor:crosshair;pointer-events:all}
.chart-dot{fill:#fff;stroke:#00704a;stroke-width:3;pointer-events:none;transition:r .16s,fill .16s,stroke-width .16s}
.chart-hit:hover+.chart-dot,.chart-hit:focus+.chart-dot{r:6;fill:#d7b76d;stroke:#006747;stroke-width:3}
.chart-hit:focus{outline:none}
.chart-tooltip{position:absolute;z-index:3;display:grid;gap:5px;min-width:136px;padding:10px 13px;border:1px solid #dce9df;border-radius:11px;background:#102f24;color:#fff;box-shadow:0 12px 30px #10251f35;pointer-events:none;transform:translateY(-2px);animation:revenueTipIn .15s ease-out}
.chart-tooltip[hidden]{display:none}
.chart-tooltip:after{content:"";position:absolute;left:50%;bottom:-6px;width:10px;height:10px;background:#102f24;border-right:1px solid #dce9df;border-bottom:1px solid #dce9df;transform:translateX(-50%) rotate(45deg)}
.chart-tooltip small{color:#a8c7b5;font-size:10px;letter-spacing:.04em}
.chart-tooltip b{font-size:14px;letter-spacing:.01em}
.chart-hit:focus-visible{stroke:#d4b05c;stroke-width:2}
@keyframes revenueTipIn{from{opacity:0;transform:translateY(3px)}to{opacity:1;transform:translateY(-2px)}}
@media(prefers-reduced-motion:reduce){.chart-tooltip,.chart-dot{animation:none!important;transition:none!important}}

/* Added modern management tools */
.metric-compare{display:flex;flex-direction:column;align-items:flex-start;gap:4px;margin-top:12px;padding-top:10px;border-top:1px solid #e9efea}
.metric-compare>span{padding:4px 8px;border-radius:999px;background:#eaf6ee;color:#08784f;font-size:10px;font-weight:750}
.metric-compare.down>span{background:#fff0ed;color:#b54737}
.metric-compare>small{color:#87948c;font-size:9px}
.order-view-switch{display:flex;align-items:center;justify-content:space-between;gap:14px;margin:18px 0 12px;padding:13px 16px;border:1px solid #e4eae5;border-radius:14px;background:#ffffffd9;box-shadow:0 6px 20px #173c2b08}
.order-view-switch>div:first-child{display:grid;gap:4px}.order-view-switch>div:first-child b{font-size:13px;color:#183529}.order-view-switch>div:first-child small{font-size:10px;color:#829188}
.order-view-switch>div:last-child{display:flex;gap:5px;padding:4px;border-radius:11px;background:#eff4f0}
.order-view-btn{padding:9px 13px;border:0;border-radius:8px;background:transparent;color:#607168;font:700 11px Inter,Arial;cursor:pointer;transition:background .2s,color .2s,box-shadow .2s,transform .2s}
.order-view-btn:hover{transform:translateY(-1px);color:#006747}.order-view-btn.active{background:#fff;color:#006747;box-shadow:0 3px 10px #0d392b14}
.order-kanban{margin:0 0 18px;animation:adminFloatIn .35s ease both}
.kanban-track{display:grid;grid-auto-columns:minmax(245px,1fr);grid-auto-flow:column;gap:13px;overflow:auto;padding:2px 2px 12px;scroll-snap-type:x proximity;scrollbar-color:#b7cbbd #edf2ee;scrollbar-width:thin}
.kanban-lane{min-width:0;max-height:calc(100vh - 250px);min-height:330px;overflow:auto;padding:11px;border:1px solid #e2e9e3;border-radius:15px;background:linear-gradient(180deg,#f5f8f5,#eef3ef);scroll-snap-align:start}
.kanban-lane>header{position:sticky;top:0;z-index:2;display:flex;align-items:center;justify-content:space-between;margin:-2px -2px 10px;padding:8px 7px;background:#f4f7f4ed;backdrop-filter:blur(10px);color:#304a3c;font-size:11px;font-weight:800}
.kanban-lane>header span{display:flex;align-items:center;gap:8px}.kanban-lane>header i{width:8px;height:8px;border-radius:50%;background:#a5b2aa;box-shadow:0 0 0 4px #a5b2aa22}.lane-confirmed>header i{background:#4f83d1;box-shadow:0 0 0 4px #4f83d122}.lane-preparing>header i{background:#a475d1;box-shadow:0 0 0 4px #a475d122}.lane-shipping>header i{background:#d29b37;box-shadow:0 0 0 4px #d29b3722}.lane-completed>header i{background:#16a36a;box-shadow:0 0 0 4px #16a36a22}.lane-cancelled>header i{background:#d55b55;box-shadow:0 0 0 4px #d55b5522}
.kanban-lane>header>b{display:grid;place-items:center;min-width:25px;height:25px;padding:0 7px;border-radius:999px;background:#fff;color:#355242;box-shadow:0 2px 7px #10251f0d}
.kanban-cards{display:grid;align-content:start;gap:9px}
.kanban-card{padding:13px;border:1px solid #e5ebe6;border-radius:12px;background:#fff;box-shadow:0 4px 13px #173c2b08;transition:transform .2s,border-color .2s,box-shadow .2s;animation:adminFloatIn .35s both}
.kanban-card:hover{transform:translateY(-2px);border-color:#c4dacb;box-shadow:0 10px 22px #173c2b12}
.kanban-card-top{display:flex;align-items:center;justify-content:space-between;gap:8px}.kanban-card-top>b{color:#006747;font-size:11px}.kanban-card-top time{color:#8b9690;font-size:9px}
