r()['email']??'Admin')?></b><small>Quản trị viên</small></span></div></div></aside><div class="content"><header class="topbar"><span class="crumb">Starbucks / <b><?=e($tabs[$tab])?></b></span><div class="toplinks"><span><?=date('d/m/Y')?></span><button type="button" class="theme-toggle" id="themeToggle" aria-label="Đổi giao diện">◐ <span>Giao diện</span></button><a href="../index.php?page=index">Mở cửa hàng ↗</a></div></header><main class="main">
<?php if($notice):?><div class="notice err"><?=e($notice)?></div><?php elseif(isset($_GET['saved'])):?><div class="notice">✓ Thay đổi đã được lưu.</div><?php endif;?>
<?php if($tab==='dashboard'):?><div class="pagehead"><div><h1>Tổng quan cửa hàng</h1><p>Theo dõi doanh thu, đơn hàng và tồn kho Starbucks.</p></div></div><form class="filters"><input type="hidden" name="tab" value="dashboard"><label>Từ ngày<input type="date" name="from" value="<?=e($from)?>"></label><label>Đến ngày<input type="date" name="to" value="<?=e($to)?>"></label><label>Nhóm biểu đồ<select name="period"><option value="day" <?=$period==='day'?'selected':''?>>Theo ngày</option><option value="month" <?=$period==='month'?'selected':''?>>Theo tháng</option><option value="year" <?=$period==='year'?'selected':''?>>Theo năm</option></select></label><button class="btn primary">Lọc doanh thu</button><a class="btn" href="?tab=dashboard">Tháng này</a></form>
<div class="cards"><article class="metric metric-revenue"><div class="metric-head">Doanh thu đã hoàn tất<span class="metric-icon">₫</span></div><strong><?=money($stats['revenue'])?></strong><small><?=date('d/m/Y',strtotime($from))?> – <?=date('d/m/Y',strtotime($to))?></small><?php if($revenueComparison):?><div class="metric-compare <?=$revenueComparison['direction']?>"><span><?=$revenueComparison['percent']===null?'Kỳ trước chưa có doanh thu':(($revenueComparison['direction']==='up'?'↑ ':'↓ ').number_format(abs($revenueComparison['percent']),1,',','.').'% so với kỳ trước')?></span><small><?=money($revenueComparison['revenue'])?> · <?=date('d/m',strtotime($revenueComparison['from']))?>–<?=date('d/m/Y',strtotime($revenueComparison['to']))?></small></div><?php endif;?></article><article class="metric"><div class="metric-head">Đơn trong khoảng lọc<span class="metric-icon">▣</span></div><strong><?=number_format((int)$stats['orders'])?></strong><small><?=number_format((int)$stats['pending'])?> đơn chờ xác nhận</small></article><article class="metric"><div class="metric-head">Sản phẩm đang quản lý<span class="metric-icon">☕</span></div><strong><?=number_format((int)$stats['products'])?></strong><small>Số phần pha được tính từ kho nguyên liệu</small></article><article class="metric"><div class="metric-head">Sắp hết hàng<span class="metric-icon">!</span></div><strong><?=number_format((int)$stats['low_stock'])?></strong><small>Đã chạm ngưỡng tối thiểu</small></article></div>
<div class="dashboard-grid"><section class="card"><div class="card-title"><div><h2>Biểu đồ doanh thu</h2><p>Chỉ tính đơn có trạng thái hoàn tất</p></div><span class="legend"><i class="dot"></i> Doanh thu</span></div><?php $vals=array_map(fn($x)=>(float)$x['revenue'],$series);$max=max($vals?:[0]);$n=max(1,count($series)-1);?><div class="chart-wrap"><svg class="chart" viewBox="0 0 740 225" role="img" aria-label="Biểu đồ doanh thu"><line class="chart-grid" x1="30" y1="30" x2="715" y2="30"/><line class="chart-grid" x1="30" y1="80" x2="715" y2="80"/><line class="chart-grid" x1="30" y1="130" x2="715" y2="130"/><line class="chart-grid" x1="30" y1="185" x2="715" y2="185"/><?php $pts=[];foreach($series as $i=>$point){$px=32+$i*(680/$n);$py=185-($max>0?(float)$point['revenue']/$max*155:0);$pts[]=round($px,1).','.round($py,1);}?><polyline fill="none" stroke="#00704a" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" points="<?=e(implode(' ',$pts))?>"/><?php foreach($series as $i=>$point):$px=round(32+$i*(680/$n),1);$py=round(185-($max>0?(float)$point['revenue']/$max*155:0),1);$chartLabel=e((string)$point['label']);$chartAmount=e(money((float)$point['revenue']));?><circle class="chart-hit" cx="<?=$px?>" cy="<?=$py?>" r="13" data-label="<?=$chartLabel?>" data-amount="<?=$chartAmount?>" tabindex="0" role="img" aria-label="<?=$chartLabel?>: <?=$chartAmount?>"><title><?=$chartLabel?> · <?=$chartAmount?></title></circle><circle class="chart-dot" cx="<?=$px?>" cy="<?=$py?>" r="4" aria-hidden="true"/><?php endforeach;?><?php if($series):?><text x="30" y="215"><?=e($series[0]['label'])?></text><text x="650" y="215"><?=e($series[count($series)-1]['label'])?></text><text x="34" y="22"><?=money($max)?></text><?php else:?><text x="280" y="110">Chưa có doanh thu hoàn tất trong khoảng thời gian này</text><?php endif;?></svg><div class="chart-tooltip" role="status" aria-live="polite" hidden></div></div></section><section class="card"><div class="card-title"><div><h2>Tình trạng đơn hàng</h2><p>Thống kê toàn bộ đơn</p></div><a class="btn small" href="?tab=orders">Xem đơn</a></div><div class="mini-list"><?php foreach($statuses as $key=>$label):$count=0;foreach($stats['statuses'] as $r)if($r['status']===$key)$count=(int)$r['total'];?><div><div class="mini-row"><span><?=e($label)?></span><b><?=$count?></b></div><div class="bar"><i style="width:<?=min(100,(int)$stats['orders']?round($count/(int)$stats['orders']*100):0)?>%"></i></div></div><?php endforeach;?></div></section></div>
<div class="dashboard-grid"><section class="card"><div class="card-title"><div><h2>Sản phẩm theo danh mục</h2><p>Số lượng món đã bán theo chi tiết đơn</p></div><a class="btn small" href="?tab=categories">Danh mục</a></div><div class="mini-list"><?php $catMax=max(array_map(fn($x)=>(int)$x['quantity'],$stats['categories'])?:[1]);foreach($stats['categories'] as $c):?><div><div class="mini-row"><span><?=e($c['name'])?></span><b><?=number_format((int)$c['quantity'])?> món</b></div><div class="bar"><i style="width:<?=max(2,round((int)$c['quantity']/$catMax*100))?>%"></i></div></div><?php endforeach;?></div></section><section class="card"><div class="card-title"><div><h2>Nguyên liệu cần nhập</h2><p>Tồn kho đã chạm ngưỡng cảnh báo</p></div><a class="btn small" href="?tab=inventory">Quản lý</a></div><?php if(!$stats['low_ingredients']):?><div class="empty">Nguyên liệu đang trên ngưỡng tối thiểu.</div><?php else:?><div class="mini-list"><?php foreach($stats['low_ingredients'] as $ingredient):?><div class="mini-row"><span><?=e($ingredient['name'])?></span><span><?=quantity_text($ingredient['stock'])?> <?=e($ingredient['unit'])?></span><b class="badge warn">Cần nhập</b></div><?php endforeach;?></div><?php endif;?>
