ction" value="save_ingredient"><label class="field">Tên nguyên liệu<input name="name" required placeholder="Ví dụ: Hạt cà phê Arabica"></label><div class="form-grid"><label class="field">Đơn vị<select name="unit"><option>g</option><option>kg</option><option>ml</option><option>l</option><option>cái</option><option>gói</option><option>viên</option></select></label><label class="field">Tồn đầu kỳ<input type="number" name="stock" min="0" step="0.001" value="0"></label><label class="field">Ngưỡng tồn thấp<input type="number" name="minimum" min="0" step="0.001" value="0"></label><label class="field">Nhà cung cấp<select name="supplier_id"><option value="0">Chưa gán</option><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>"><?=e($s['ten'])?></option><?php endforeach;?></select></label></div><button class="btn primary">＋ Lưu nguyên liệu</button></form></section></div>
