d><?=number_format((float)$a['tong_gio'],2,',','.')?></td><td><b><?=money(round((float)$a['tong_gio']*20000))?></b></td></tr><?php endforeach;?><?php if(!$attendanceRecords):?><tr><td colspan="6" class="empty">Chưa có chấm công trong tháng này.</td></tr><?php endif;?></tbody></table></div></section><?php elseif($tab==='deletions'):?><div class="pagehead"><div><h1>Yêu cầu xóa tài khoản</h1><p>Admin xác nhận trước khi tài khoản bị vô hiệu hóa và thông tin cá nhân được ẩn.</p></div></div><section class="card table-card"><div class="scroll"><table><thead><tr><th>Tài khoản</th><th>Ngày gửi</th><th>Trạng thái</th><th>Xử lý</th></tr></thead><tbody><?php foreach($deletionRequests as $r):?><tr><td><b><?=e($r['ten_nguoi_dung'])?></b><small><?=e($r['email'])?></small></td><td><?=date('d/m/Y H:i',strtotime($r['created_at']))?></td><td><?php if($r['trang_thai']==='cho_duyet'):?><span class="badge warn">Chờ admin duyệt</span><?php elseif($r['trang_thai']==='da_duyet'):?><span class="badge">Đã duyệt</span><?php else:?><span class="badge off">Đã từ chối</span><?php endif;?></td><td><?php if($r['trang_thai']==='cho_duyet'):?><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="review_deletion"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="decision" value="da_duyet"><button class="btn small primary">Duyệt</button></form> <form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="review_deletion"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="decision" value="tu_choi"><button class="btn small">Từ chối</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?><?php if(!$deletionRequests):?><tr><td colspan="4" class="empty">Chưa có yêu cầu xóa tài khoản.</td></tr><?php endif;?></tbody></table></div></section>
<?php else:?><div class="pagehead"><div><h1>Nhân viên</h1><p>Nhân viên cửa hàng, hồ sơ làm việc và ca làm đã đăng ký.</p></div><a class="btn primary" href="?tab=staff&new=1">＋ Thêm nhân viên</a></div><?php if(isset($_GET['new'])||$editing):?><section class="card"><div class="card-title"><div><h2><?=$editing?'Thông tin nhân viên':'Tạo tài khoản nhân viên'?></h2><p>Tài khoản này có quyền nhân viên và sử dụng chức năng chấm công.</p></div></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_staff"><input type="hidden" name="id" value="<?=e($editing['id']??0)?>"><div class="form-grid"><label class="field">Họ tên<input required name="name" value="<?=e($editing['name']??'')?>"></label><label class="field">Email đăng nhập<input required type="email" name="email" value="<?=e($editing['email']??'')?>"></label><label class="field">Số điện thoại<input name="phone" value="<?=e($editing['phone']??'')?>"></label><label class="field">Loại hình làm việc<select name="employment_type" required><option value="full_time" <?=($editing['employment_type']??'full_time')==='full_time'?'selected':''?>>Full time</option><option value="part_time" <?=($editing['employment_type']??'')==='part_time'?'selected':''?>>Part time</option></select></label><label class="field">Ca bắt đầu<input type="time" name="shift_start" value="<?=e($editing['shift_start']??'08:00')?>" required></label><label class="field">Ca kết thúc<input type="time" name="shift_end" value="<?=e($editing['shift_end']??'17:00')?>" required></label><label class="field">Mật khẩu <?=$editing?'(để trống nếu không đổi)':''?><input type="password" name="password" <?=$editing?'':'required minlength="8"'?> minlength="8" autocomplete="new-password"></label><div class="field full">Quyền truy cập: <span class="badge">Nhân viên cửa hàng</span></div></div><div class="actions"><button class="btn primary">Lưu nhân viên</button><a href="?tab=staff" class="btn">Hủy</a></div></form></section><?php endif;?><section class="card"><div class="table-head" style="padding:0 0 15px;border:0"><h2><?=count($staff)?> nhân viên cửa hàng</h2></div><?php if(!$staff):?><div class="empty">Chưa có nhân viên nào.</div><?php else:?><div class="staff-grid"><?php foreach($staff as $s):?><article class="staff-card"><div class="prod"><span class="avatar"><?=e(mb_substr($s['name'],0,1))?></span><span class="staff-tag badge">Staff</span><span class="staff-name"><b><?=e($s['name'])?></b></span><span class="grow"></span><a class="btn small" href="?tab=staff&edit=<?=$s['id']?>">Sửa</a></div><div class="staff-meta"><div><span>Email đăng nhập</span><b><?=e($s['email'])?></b></div><div><span>Số điện thoại</span><b><?=e($s['phone']?:'Chưa cập nhật')?></b></div><div><span>Giới tính</span><b><?=e(match($s['gender']??''){ 'nam'=>'Nam','nu'=>'Nữ','khac'=>'Khác',default=>'Chưa cập nhật'})?></b></div><div><span>Ngày sinh</span><b><?=!empty($s['birth_date'])?date('d/m/Y',strtotime($s['birth_date'])):'Chưa cập nhật'?></b></div><div><span>Loại hình</span><b><?=($s['employment_type']??'full_time')==='part_time'?'Part time':'Full time'?></b></div><div><span>Ca làm việc</span><b><?=e(substr((string)($s['shift_start']??'08:00'),0,5))?>–<?=e(substr((string)($s['shift_end']??'17:00'),0,5))?></b></div><div><span>Mã nhân viên</span><b>NV-<?=str_pad((string)$s['id'],4,'0',STR_PAD_LEFT)?></b></div><div><span>Ngày tham gia</span><b><?=date('d/m/Y',strtotime($s['created_at']))?></b></div><div><span>Tình trạng</span><b><?=$s['employment_end_date']?'Đã nghỉ việc':'Đang làm việc'?></b></div></div><form method="post" style="margin-top:12px" onsubmit="return confirm('Cho nhân viên này nghỉ việc? Nhân viên sẽ không thể đăng nhập chấm công; lịch sử chấm công và lương vẫn được giữ.')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="end_staff"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="btn small danger" <?=!empty($s['employment_end_date'])?'disabled title="Nhân viên đã nghỉ việc"':''?>>Cho nghỉ việc</button></form></article><?php endforeach;?></div><?php endif;?></section><?php endif;?>
<p class="footnote">Dữ liệu trong phạm vi <?=e($from)?> — <?=e($to)?> · Thời gian máy chủ: <?=date('H:i')?></p></main></div></div><script>
document.querySelectorAll('.chart-wrap').forEach(function(wrap){
 const tip=wrap.querySelector('.chart-tooltip');
 function show(point){tip.innerHTML='<small>'+point.dataset.label+'</small><b>'+point.dataset.amount+'</b>';tip.hidden=false;const wr=wrap.getBoundingClientRect(),pr=point.getBoundingClientRect();const left=pr.left-wr.left+pr.width/2;const top=pr.top-wr.top;tip.style.left=Math.max(8,Math.min(wrap.clientWidth-tip.offsetWidth-8,left-tip.offsetWidth/2))+'px';tip.style.top=Math.max(2,top-tip.offsetHeight-12)+'px';}
 wrap.querySelectorAll('.chart-hit').forEach(function(point){point.addEventListener('pointerenter',function(){show(point)});point.addEventListener('focus',function(){show(point)});point.addEventListener('pointerleave',function(){tip.hidden=true});point.addEventListener('blur',function(){tip.hidden=true});});
});

const themeButton=document.getElementById('themeToggle');
function setAdminTheme(theme){document.documentElement.dataset.adminTheme=theme;try{localStorage.setItem('tmdt6-admin-theme',theme)}catch(e){}if(themeButton){themeButton.innerHTML=(theme==='dark'?'☀':'◐')+' <span>'+(theme==='dark'?'Sáng':'Tối')+'</span>';themeButton.setAttribute('aria-label',theme==='dark'?'Chuyển sang giao diện sáng':'Chuyển sang giao diện tối')}}
setAdminTheme(document.documentElement.dataset.adminTheme||'light');
if(themeButton)themeButton.addEventListener('click',()=>setAdminTheme(document.documentElement.dataset.adminTheme==='dark'?'light':'dark'));
document.querySelectorAll('[data-order-view]').forEach(button=>button.addEventListener('click',()=>{const board=document.getElementById('orderBoard'),table=document.getElementById('orderTable'),isBoard=button.dataset.orderView==='board';board.hidden=!isBoard;table.hidden=isBoard;document.querySelectorAll('[data-order-view]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button?'true':'false')})}));
const inventoryDialog=document.getElementById('inventoryDialog');document.querySelectorAll('.menu-edit-trigger').forEach(button=>button.addEventListener('click',()=>{if(!inventoryDialog)return;document.getElementById('inventoryId').value=button.dataset.id;document.getElementById('inventoryTitle').textContent=button.dataset.name;document.getElementById('inventoryPrice').value=button.dataset.price;inventoryDialog.showModal()}));
const progress=document.getElementById('adminProgress');function startProgress(){if(progress){progress.classList.remove('done');progress.classList.add('running')}}document.querySelectorAll('.nav a,.side-bottom a,.toplinks a:not(.theme-toggle)').forEach(a=>a.addEventListener('click',startProgress));document.querySelectorAll('form').forEach(form=>form.addEventListener('submit',startProgress));window.addEventListener('pageshow',()=>{if(progress){progress.classList.remove('running');progress.classList.add('done');setTimeout(()=>progress.classList.remove('done'),250)}});
</script></body></html>
